INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('2a45fc4f-ae41-42e5-abd7-98292aa27fa0', '7983b234-5899-42e9-92cf-1ddd65a52e91', NULL, '{"tags": ["Supabase", "Flutter", "Deployment"], "type": "multiple_choice", "hints": [], "choices": [{"id": 0, "text": "Sử dụng biến môi trường (environment variables) và một file `.env` được loại trừ khỏi Git.", "isCorrect": true}, {"id": 1, "text": "Nhúng trực tiếp các khóa API vào mã nguồn Dart của ứng dụng.", "isCorrect": false}, {"id": 2, "text": "Lưu trữ khóa API trong local storage của trình duyệt.", "isCorrect": false}, {"id": 3, "text": "Gửi khóa API qua URL parameters mỗi khi thực hiện một request.", "isCorrect": false}], "difficulty": 4, "explanation": "", "override_text": "Khi triển khai ứng dụng Flutter lên Supabase, bạn nên sử dụng chiến lược nào để quản lý các khóa API một cách an toàn, đặc biệt là các khóa `SUPABASE_URL` và `SUPABASE_ANON_KEY`?", "learningObjectives": []}', 1.00, NULL, 1) ON CONFLICT DO NOTHING;
INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('3160f2f0-89f2-4147-8a0f-72f1b2a367b1', '7983b234-5899-42e9-92cf-1ddd65a52e91', NULL, '{"tags": ["Supabase", "CORS", "Flutter"], "type": "multiple_choice", "hints": [], "choices": [{"id": 0, "text": "Tắt hoàn toàn CORS để cho phép tất cả các nguồn truy cập.", "isCorrect": false}, {"id": 1, "text": "Cho phép domain của ứng dụng Flutter (ví dụ: `https://your-app.com`) trong cài đặt CORS của Supabase.", "isCorrect": true}, {"id": 2, "text": "Chỉ cho phép các request từ localhost.", "isCorrect": false}, {"id": 3, "text": "Không cần cấu hình CORS vì Supabase tự động xử lý.", "isCorrect": false}], "difficulty": 4, "explanation": "", "override_text": "Để đảm bảo ứng dụng Flutter hoạt động chính xác sau khi triển khai lên Supabase, bạn cần cấu hình CORS (Cross-Origin Resource Sharing) như thế nào?", "learningObjectives": []}', 1.00, NULL, 2) ON CONFLICT DO NOTHING;
INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('8f42e977-23d8-45e1-bf3f-537d3a1ef9d7', '7983b234-5899-42e9-92cf-1ddd65a52e91', NULL, '{"tags": ["Supabase", "Functions", "Authentication"], "type": "multiple_choice", "hints": [], "choices": [{"id": 0, "text": "Supabase functions tự động xác thực người dùng dựa trên session của ứng dụng Flutter.", "isCorrect": false}, {"id": 1, "text": "Không cần xác thực người dùng trong Supabase functions để giảm độ phức tạp.", "isCorrect": false}, {"id": 2, "text": "Cần xác thực người dùng trong Supabase functions bằng cách kiểm tra JWT (JSON Web Token) được gửi từ ứng dụng Flutter.", "isCorrect": true}, {"id": 3, "text": "Sử dụng một khóa bí mật (secret key) được chia sẻ giữa ứng dụng Flutter và Supabase function.", "isCorrect": false}], "difficulty": 4, "explanation": "", "override_text": "Khi sử dụng Supabase functions để thực hiện các tác vụ backend cho ứng dụng Flutter, bạn cần chú ý điều gì về xác thực (authentication) người dùng?", "learningObjectives": []}', 1.00, NULL, 3) ON CONFLICT DO NOTHING;
