INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('ee000206-0000-4a00-a000-000000000001', 'dd000200-0000-4a00-a000-000000000001', '749b88f5-fe20-5506-a506-ea403374834a', '{"tags": [], "type": "multiple_choice", "hints": [], "choices": [{"id": 0, "text": "8 bytes", "isCorrect": false}, {"id": 1, "text": "16 bytes", "isCorrect": false}, {"id": 2, "text": "20 bytes", "isCorrect": true}, {"id": 3, "text": "32 bytes", "isCorrect": false}], "difficulty": 2, "explanation": "Header TCP tối thiểu 20 bytes.", "override_text": "Header TCP có kích thước tối thiểu bao nhiêu byte?", "learningObjectives": []}', 1.00, NULL, 6) ON CONFLICT DO NOTHING;
INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('ee000207-0000-4a00-a000-000000000001', 'dd000200-0000-4a00-a000-000000000001', 'd8ebfc19-a87e-50f0-99cf-22622603ba26', '{"tags": [], "type": "multiple_choice", "hints": [], "choices": [{"id": 0, "text": "UDP đảm bảo truyền tin cậy hơn TCP", "isCorrect": false}, {"id": 1, "text": "TCP có cơ chế kiểm soát lỗi, UDP không có", "isCorrect": true}, {"id": 2, "text": "TCP và UDP đều không có flow control", "isCorrect": false}, {"id": 3, "text": "UDP có three-way handshake", "isCorrect": false}], "difficulty": 3, "explanation": "TCP đảm bảo truyền tin cậy, UDP không đảm bảo nhưng nhanh hơn. TCP có cơ chế kiểm soát lỗi và flow control.", "override_text": "So sánh TCP và UDP: phát biểu nào đúng?", "learningObjectives": []}', 4.00, NULL, 7) ON CONFLICT DO NOTHING;
INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('ee000301-0000-4a00-a000-000000000001', 'dd000300-0000-4a00-a000-000000000001', '723263f8-3a08-5301-b7a2-d55084ede4c3', '{"tags": [], "type": "multiple_choice", "hints": [], "choices": [{"id": 0, "text": "Lớp A", "isCorrect": false}, {"id": 1, "text": "Lớp B", "isCorrect": false}, {"id": 2, "text": "Lớp C", "isCorrect": true}, {"id": 3, "text": "Lớp D", "isCorrect": false}], "difficulty": 2, "explanation": "192.168.x.x thuộc lớp C (Class C).", "override_text": "Địa chỉ IP 192.168.1.0/24 thuộc lớp nào?", "learningObjectives": []}', 0.50, NULL, 1) ON CONFLICT DO NOTHING;
INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('d169c2ff-a654-4b60-89d9-8f2f4023201f', 'ebd61f1b-a2f4-42ee-84b9-bba0fdc3d03d', NULL, '{"tags": ["tự luận", "test chức năng"], "type": "essay", "explanation": "Để tạo 5 câu tự luận dễ dùng để test chức năng của app, bạn có thể tập trung vào các kịch bản sử dụng cụ thể và yêu cầu người dùng thực hiện các hành động cụ thể. Ví dụ, bạn có thể yêu cầu người dùng đăng ký tài khoản, thêm sản phẩm vào giỏ hàng, hoặc thực hiện thanh toán trực tuyến.", "override_text": "Xin hãy mô tả cách tạo 5 câu tự luận dễ dùng để test chức năng của app, bao gồm cả ví dụ cụ thể."}', 1.00, NULL, 1) ON CONFLICT DO NOTHING;
INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('40c28388-7512-4abd-ad23-4ea8f7973a91', 'ebd61f1b-a2f4-42ee-84b9-bba0fdc3d03d', NULL, '{"tags": ["phát triển phần mềm", "quan trọng"], "type": "essay", "explanation": "Các câu tự luận giúp kiểm tra khả năng tương tác của người dùng với ứng dụng, từ đó xác định các lỗi và điểm cần cải thiện trong quá trình phát triển phần mềm. Điều này giúp phát triển phần mềm trở nên hiệu quả và đáp ứng được nhu cầu của người dùng.", "override_text": "Hãy giải thích tại sao các câu tự luận dễ dùng để test chức năng của app là quan trọng trong quá trình phát triển phần mềm."}', 1.00, NULL, 2) ON CONFLICT DO NOTHING;
INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('1a0189fb-7520-491a-b7bf-4838c13f14dd', 'ebd61f1b-a2f4-42ee-84b9-bba0fdc3d03d', NULL, '{"tags": ["dữ liệu thực", "tạo câu tự luận"], "type": "essay", "override_text": "Xin hãy mô tả cách tạo 5 câu tự luận dễ dùng để test chức năng của app trong trường hợp có dữ liệu thực (số, ngày, tên người)."}', 1.00, NULL, 3) ON CONFLICT DO NOTHING;
INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('7de251a9-d64c-4e41-8a77-2a63070e495a', 'ebd61f1b-a2f4-42ee-84b9-bba0fdc3d03d', NULL, '{"tags": ["phát triển phần mềm", "áp dụng thực tế"], "type": "essay", "override_text": "Hãy giải thích tại sao các câu tự luận dễ dùng để test chức năng của app cần được áp dụng thực tế trong quá trình phát triển phần mềm."}', 1.00, NULL, 4) ON CONFLICT DO NOTHING;
INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('846466fa-af87-4305-a9ef-c19952c0f421', 'ebd61f1b-a2f4-42ee-84b9-bba0fdc3d03d', NULL, '{"tags": ["người dùng khác nhau", "tạo câu tự luận"], "type": "essay", "override_text": "Xin hãy mô tả cách tạo 5 câu tự luận dễ dùng để test chức năng của app trong trường hợp có nhiều người dùng khác nhau."}', 1.00, NULL, 5) ON CONFLICT DO NOTHING;
