INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('ee000602-0000-4a00-a000-000000000001', 'dd000600-0000-4a00-a000-000000000001', 'fadbe264-855f-552b-af04-baae3b73d35b', '{"tags": [], "type": "multiple_choice", "hints": [], "choices": [{"id": 0, "text": "Giống nhau", "isCorrect": false}, {"id": 1, "text": "Trả về tất cả bản ghi bảng trái", "isCorrect": true}, {"id": 2, "text": "Trả về tất cả bảng phải", "isCorrect": false}, {"id": 3, "text": "Chỉ trả về NULL", "isCorrect": false}], "difficulty": 2, "explanation": "LEFT JOIN trả về tất cả bản ghi bảng trái, kể cả không khớp.", "override_text": "LEFT JOIN khác INNER JOIN ở điểm nào?", "learningObjectives": []}', 1.00, NULL, 2) ON CONFLICT DO NOTHING;
