INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('ee000607-0000-4a00-a000-000000000001', 'dd000600-0000-4a00-a000-000000000001', '7aa39ff3-a367-5239-b282-0b891ef2d10e', '{"tags": [], "type": "multiple_choice", "hints": [], "choices": [{"id": 0, "text": "Dùng GROUP BY + HAVING AVG(score) > 7", "isCorrect": true}, {"id": 1, "text": "Dùng WHERE AVG(score) > 7", "isCorrect": false}, {"id": 2, "text": "Không cần GROUP BY", "isCorrect": false}, {"id": 3, "text": "Dùng DISTINCT thay GROUP BY", "isCorrect": false}], "difficulty": 3, "explanation": "SELECT class_id, COUNT(*) FROM students GROUP BY class_id HAVING AVG(score) > 7;", "override_text": "Viết truy vấn đếm số sinh viên mỗi lớp có điểm trung bình > 7?", "learningObjectives": []}', 4.00, NULL, 7) ON CONFLICT DO NOTHING;
