INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('ee000b09-0000-4a00-a000-000000000001', 'dd000b00-0000-4a00-a000-000000000001', 'd715e284-f244-5c16-a91b-d0f475ead78a', '{"tags": [], "type": "multiple_choice", "hints": [], "choices": [{"id": 0, "text": "TCP tin cậy có handshake, UDP nhanh không đảm bảo, tùy use case", "isCorrect": true}, {"id": 1, "text": "TCP luôn tốt hơn UDP", "isCorrect": false}, {"id": 2, "text": "UDP luôn tốt hơn TCP", "isCorrect": false}, {"id": 3, "text": "Không có sự khác biệt", "isCorrect": false}], "difficulty": 3, "explanation": "Connection-oriented (TCP): tin cậy, có handshake. Connectionless (UDP): nhanh, nhẹ, không đảm bảo.", "override_text": "So sánh connection-oriented vs connectionless transport: phân tích ưu nhược điểm?", "learningObjectives": []}', 2.00, NULL, 9) ON CONFLICT DO NOTHING;
