INSERT INTO public.assignment_questions (id, assignment_id, question_id, custom_content, points, rubric, order_idx) VALUES ('6d6c7293-275d-4b46-a8d4-d1f58aa065bb', '096e30b5-7292-4a8f-8942-6dec75e0494a', NULL, '{"tags": ["tạo câu hỏi toán cộng lớp 3", "số tiền"], "type": "multiple_choice", "choices": [{"id": 0, "text": "8", "isCorrect": false}, {"id": 1, "text": "10", "isCorrect": false}, {"id": 2, "text": "12", "isCorrect": true}, {"id": 3, "text": "15", "isCorrect": false}], "override_text": "Hai bạn A và B có số tiền 15 và 7, họ muốn mua một chiếc bánh có giá 25. Nếu họ chia tiền đều, mỗi người sẽ có bao nhiêu tiền?"}', 1.00, NULL, 1) ON CONFLICT DO NOTHING;
