INSERT INTO public.teacher_notes (id, teacher_id, student_id, content, is_private, created_at) VALUES ('7263a755-1a06-517f-8add-70ec5288e288', '51e467a2-9033-5e85-b666-164ea075f6c9', 'b3e27ac4-a528-5174-92f8-99a8f273eb84', 'Sinh viên chăm chỉ, nộp bài đúng hạn. Cần cải thiện phần subnetting.', true, '2026-02-14 08:00:00+00') ON CONFLICT DO NOTHING;
INSERT INTO public.teacher_notes (id, teacher_id, student_id, content, is_private, created_at) VALUES ('9a88353a-1044-595d-bd27-533c834e2f43', '51e467a2-9033-5e85-b666-164ea075f6c9', 'd0318e10-3203-5130-9992-fba4053f5edb', 'Vắng nhiều buổi, cần nhắc nhở. Điểm giữa kỳ thấp.', true, '2026-02-14 08:00:00+00') ON CONFLICT DO NOTHING;
INSERT INTO public.teacher_notes (id, teacher_id, student_id, content, is_private, created_at) VALUES ('19384b84-e56d-517e-ac16-5747172e57b3', '51e467a2-9033-5e85-b666-164ea075f6c9', 'c4bf37f2-87e8-5a5c-b831-8d92e1d51e17', 'Có khả năng lãnh đạo nhóm tốt. Giúp đỡ bạn cùng nhóm.', true, '2026-02-14 08:00:00+00') ON CONFLICT DO NOTHING;
INSERT INTO public.teacher_notes (id, teacher_id, student_id, content, is_private, created_at) VALUES ('b1000001-0000-0000-0000-000000000001', '51e467a2-9033-5e85-b666-164ea075f6c9', 'b3e27ac4-a528-5174-92f8-99a8f273eb84', 'Em Huy nắm vững cú pháp Python nhưng còn lúng túng với khái niệm tham chiếu biến. Cần chú ý câu hỏi liên quan đến mutable objects. Có tiến bộ rõ ở bài Flask.', true, '2026-03-14 08:00:00+00') ON CONFLICT DO NOTHING;
